#amp-hc{box-sizing:border-box;font-family:montserrat,sans-serif;color:#fff;align-self:start;justify-self:start;z-index:2;position:relative;display:flex;flex-direction:column;background:#000;border:1px solid #D4AF37;border-radius:10px;padding:16px 20px 14px;overflow:hidden}
#amp-hc *{box-sizing:border-box}
#amp-hc .hd{display:flex;align-items:center;gap:10px;margin-bottom:10px}
#amp-hc .hd img{width:40px;height:40px;border-radius:50%;border:2px solid #D4AF37;object-fit:cover}
#amp-hc .hd .t{font:700 16px roboto-bold,roboto,sans-serif;color:#fff;line-height:1.2}
#amp-hc .hd .t small{display:block;font:400 12px montserrat,sans-serif;color:#D4AF37}
#amp-hc .hd .lv{margin-left:auto;font:700 10px montserrat,sans-serif;color:#111;background:#D4AF37;border-radius:20px;padding:4px 10px;letter-spacing:.05em;white-space:nowrap}
#amp-hc .bd{flex:1;display:flex;flex-direction:column;justify-content:space-between;min-height:0}
#amp-hc .n1{display:flex;align-items:center;gap:12px;padding:6px 12px;border-radius:8px;background:linear-gradient(90deg,rgba(212,175,55,.22),rgba(212,175,55,.04))}
#amp-hc .n1 .r{font:800 28px roboto-bold,roboto,sans-serif;color:#D4AF37;min-width:40px}
#amp-hc .n1 .s{font-weight:700;font-size:16px}
#amp-hc .row{display:flex;gap:12px;align-items:center;padding:3px 12px;border-bottom:1px solid rgba(255,255,255,.08)}
#amp-hc .row:last-child{border:0}
#amp-hc .row .r{font:700 15px roboto-bold,roboto,sans-serif;color:#D4AF37;min-width:40px}
#amp-hc .s{font-size:13px;font-weight:600;line-height:1.2;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#amp-hc .a{font-size:11px;color:rgba(255,255,255,.7);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#amp-hc .r+div{min-width:0}
#amp-hc .mv{font-size:10px;color:#D4AF37;margin-left:6px;font-weight:600}
#amp-hc .ld{font-size:13px;color:rgba(255,255,255,.7);padding:10px 0}
#amp-hc .bt{display:flex;justify-content:center;align-items:center;gap:8px;margin-top:10px;background:#D4AF37;color:#111;font:700 14px montserrat,sans-serif;padding:9px 16px;border-radius:6px;text-decoration:none}
#amp-hc .bt:hover{background:#e6c556}
.amp-hc-on #comp-mq3iuso9,.amp-hc-on #comp-mq3ivak8,.amp-hc-on #comp-mq3ivxqe,.amp-hc-on #comp-mq3ixnue{display:none!important}
@media (max-width:750px){#amp-hc{margin:0 16px 28px;height:auto!important;width:auto!important}#amp-hc .bd{gap:4px}}
#amp-hh{box-sizing:border-box;text-align:center;font-family:montserrat,sans-serif;color:#fff;align-self:start;justify-self:start;z-index:2;position:relative}
#amp-hh .k{font:700 13px roboto-bold,roboto,sans-serif;color:#D4AF37;letter-spacing:.08em}
#amp-hh .k i{display:inline-block;width:8px;height:8px;border-radius:50%;background:#D4AF37;margin-right:8px;vertical-align:1px;animation:amphc 1.6s infinite}
@keyframes amphc{50%{opacity:.3}}
#amp-hh h2{margin:8px 0 8px;font:700 36px/1.15 roboto-bold,roboto,sans-serif;color:#fff}
#amp-hh h2 b{color:#D4AF37}
#amp-hh p{margin:0 auto;max-width:760px;font-size:15px;line-height:1.5;color:rgba(255,255,255,.82)}
@media (max-width:750px){#amp-hh{padding:24px 16px 16px}#amp-hh h2{font-size:26px}#amp-hh p{font-size:14px}}


