#amp-greet{position:fixed;right:18px;bottom:112px;z-index:2147483001;max-width:330px;width:calc(100vw - 36px);box-sizing:border-box;background:#0b0a0d;color:#fff;border:1px solid #D4AF37;border-radius:16px;padding:16px 16px 14px;font-family:Montserrat,Arial,Helvetica,sans-serif;box-shadow:0 12px 30px rgba(0,0,0,.45);opacity:0;transform:translateY(14px);transition:opacity .35s ease,transform .35s ease}
#amp-greet.show{opacity:1;transform:none}
#amp-greet .ag-top{display:flex;align-items:center;gap:8px;margin-bottom:8px}
#amp-greet .ag-dot{width:8px;height:8px;border-radius:50%;background:#ff3b5c;flex:none}
#amp-greet .ag-tag{color:#D4AF37;font-weight:700;letter-spacing:.14em;font-size:11px}
#amp-greet .ag-x{margin-left:auto;background:none;border:0;color:#b9b3c2;font-size:20px;line-height:1;cursor:pointer;padding:0 2px}
#amp-greet .ag-x:hover{color:#fff}
#amp-greet .ag-msg{font-size:15px;line-height:1.45;margin:0 0 12px}
#amp-greet .ag-btn{border:0;cursor:pointer;font-family:inherit;display:inline-flex;align-items:center;gap:6px;background:#D4AF37;color:#111;text-decoration:none;font-weight:700;border-radius:999px;padding:8px 16px;font-size:13px}
#amp-greet .ag-btn:hover{background:#e8c650}
@media (max-width:480px){#amp-greet{right:12px;left:12px;width:auto;max-width:none;bottom:104px}}


(function(){
  // Add a page here: path (lowercase, no trailing slash) -> message, button text, button link
  var MSG={
    "/":{tag:"WELCOME",text:"Welcome to AmpliPhy, Black and Out Loud. Press play and listen live.",btn:"▶ Listen Live",href:"https://www.ampliphy.net/listen-live"},
    "/weekly-top-40":{tag:"DJ BAKER",text:"Catch DJ Baker's Weekly Top 40 live, Saturdays 6 to 10 PM ET 🎧",btn:"▶ Listen Live",href:"https://www.ampliphy.net/listen-live"},
    "/submit-music":{tag:"CALLING ALL ARTISTS",text:"Indie artists, we want your music! Submit here and you could be heard on AmpliPhy.",btn:"Submit Your Music ↓",scroll:"form"},
    "/category/all-products":{tag:"AMPLIPHY SHOP",text:"Rep the station! Every purchase supports Black LGBTQ voices on AmpliPhy.",btn:"Shop Now ↓",scroll:"[data-hook=\"product-list\"]"}
  };
  var timer=null, last=null;
  function check(){
    var p=(location.pathname||"/").toLowerCase().replace(/\/+$/,"")||"/";
    if(p===last) return; last=p;
    clearTimeout(timer);
    var old=document.getElementById("amp-greet"); if(old) old.remove();
    var m=MSG[p]; if(!m) return;
    var key="ampGreet:"+p;
    try{ if(sessionStorage.getItem(key)) return; }catch(e){}
    timer=setTimeout(function(){ show(m,key); },3500);
  }
  function show(m,key){
    if(document.getElementById("amp-greet")) return;
    var d=document.createElement("div"); d.id="amp-greet"; d.setAttribute("role","status");
    d.innerHTML='      ×    '+(m.scroll?'  ':'  ');
    d.querySelector(".ag-tag").textContent=m.tag;
    d.querySelector(".ag-msg").textContent=m.text;
    var a=d.querySelector(".ag-btn"); a.textContent=m.btn; if(!m.scroll) a.href=m.href;
    function close(){ d.classList.remove("show"); setTimeout(function(){ d.remove(); },400); }
    if(m.scroll){ a.onclick=function(ev){ ev.preventDefault(); ev.stopPropagation(); var t=document.querySelector(m.scroll); if(t) window.scrollTo({top:t.getBoundingClientRect().top+window.scrollY-100,behavior:"smooth"}); close(); }; }
    d.querySelector(".ag-x").onclick=close;
    document.body.appendChild(d);
    requestAnimationFrame(function(){ d.classList.add("show"); });
    try{ sessionStorage.setItem(key,"1"); }catch(e){}
  }
  check(); setInterval(check,1000);
})();
